class Solution:
    def getImportance(self, employees: list['Employee'], id: int) -> int:
        by_id = {employee.id: employee for employee in employees}
        pending, total = [id], 0
        while pending:
            employee = by_id[pending.pop()]
            total += employee.importance
            pending.extend(employee.subordinates)
        return total
